import { streamText } from 'ai';
import { createMCPClient } from '@ai-sdk/mcp';

const sea = await createMCPClient({ transport: { type: 'http', url: 'https://mareliberum.dev/mcp' } });
const result = streamText({
  model: 'anthropic/claude-sonnet-5.5',
  tools: await sea.tools(),
  prompt: 'Find an MCP server for Postgres.',
  onEnd: async () => { await sea.close(); },
});
for await (const text of result.textStream) process.stdout.write(text);
